@pytest.mark.unit
def test_module_name_regular_module():
    """AC7: A regular .py file in a src-layout package is mapped to its importable name."""
    assert _module_name("src/omnimarket/a/b.py") == "omnimarket.a.b"


@pytest.mark.unit
def test_module_name_init_file():
    """AC7: An __init__.py file is mapped to the package name, not the module name."""
    assert _module_name("src/omnimarket/a/__init__.py") == "omnimarket.a"


@pytest.mark.unit
def test_module_name_top_level():
    """AC7: A top-level module in the src layout."""
    assert _module_name("src/omnimarket/foo.py") == "omnimarket.foo"


@pytest.mark.unit
def test_module_name_top_level_init():
    """AC7: A top-level package __init__.py."""
    assert _module_name("src/omnimarket/__init__.py") == "omnimarket"


@pytest.mark.unit
def test_module_name_deeply_nested():
    """AC7: A deeply nested module."""
    assert _module_name("src/omnimarket/a/b/c/d.py") == "omnimarket.a.b.c.d"


@pytest.mark.unit
def test_module_name_deeply_nested_init():
    """AC7: A deeply nested package __init__.py."""
    assert _module_name("src/omnimarket/a/b/c/__init__.py") == "omnimarket.a.b.c"


@pytest.mark.unit
def test_cap_exactly_at_limit():
    """AC8: Text of exactly the limit is left untouched and not truncated."""
    text = "x" * 100
    capped, truncated = _cap(text, 100)
    assert capped == text
    assert truncated is False


@pytest.mark.unit
def test_cap_one_over_limit():
    """AC8: Text one character over the limit is truncated with the marker."""
    text = "x" * 101
    capped, truncated = _cap(text, 100)
    assert capped == "x" * 100 + "\n# ... truncated ...\n"
    assert truncated is True


@pytest.mark.unit
def test_cap_under_limit():
    """AC8: Text under the limit is left untouched and not truncated."""
    text = "hello"
    capped, truncated = _cap(text, 100)
    assert capped == "hello"
    assert truncated is False


@pytest.mark.unit
def test_cap_empty_text():
    """AC8: Empty text is left untouched and not truncated."""
    capped, truncated = _cap("", 100)
    assert capped == ""
    assert truncated is False


@pytest.mark.unit
def test_cap_zero_limit():
    """AC8: A zero limit truncates any non-empty text."""
    text = "abc"
    capped, truncated = _cap(text, 0)
    assert capped == "\n# ... truncated ...\n"
    assert truncated is True


@pytest.mark.unit
def test_cap_zero_limit_empty_text():
    """AC8: A zero limit with empty text is not truncated."""
    capped, truncated = _cap("", 0)
    assert capped == ""
    assert truncated is False


@pytest.mark.unit
def test_cap_large_text():
    """AC8: Large text is truncated to the limit plus the marker."""
    text = "a" * 10_000
    capped, truncated = _cap(text, 100)
    assert len(capped) == 100 + len("\n# ... truncated ...\n")
    assert truncated is True
    assert capped.startswith("a" * 100)
    assert capped.endswith("\n# ... truncated ...\n")


@pytest.mark.unit
def test_cap_with_max_previous_test_chars():
    """AC8: The REPAIR prompt caps the previous test at MAX_PREVIOUS_TEST_CHARS."""
